    async function restoreCourse(course) {
        await action(`/courses/${course.id}/rejoin/`, 'POST', {});
    }
    async function withdrawCourse(course) {
        const confirmed = window.confirm(`Withdraw from "${course.title}"? Your access will be removed. Any completed payment will remain captured; no refund will be issued.`);
        if (!confirmed) return;
        await action(`/courses/${course.id}/withdraw/`, 'POST', {});
        if (selectedCourse && Number(selectedCourse.id) === Number(course.id)) {
            setSelectedCourse(null);
            setPage('My learning');
        }
    }
    async function enroll(course) {
        if (paymentCreatingCourseId !== null) return;
        if (course.previously_paid) {
            await restoreCourse(course);
            return;
        }
        if (Number(course.price || 0) > 0) {
            const amount = `$${Number(course.price).toFixed(2)} ${course.currency || 'USD'}`;
            if (!window.confirm(`You're about to purchase "${course.title}" for ${amount}. You'll be redirected to PayPal to complete your payment. Continue?`)) return;
            setError('');
            setPaymentCreatingCourseId(course.id);
            try {
                const order = await api('/payments/create-order/', { method: 'POST', body: JSON.stringify({ course_id: course.id }) });
                if (order.return_url) {
                    window.location.href = order.return_url;
                    return;
                }
                if (!order.approve_url) throw new Error('PayPal did not return an approval URL.');
                window.location.href = order.approve_url;
            } catch (err) {
                setError(err.message);
                if (err.message?.toLowerCase().includes('already paid')) await refresh();
            } finally {
                setPaymentCreatingCourseId(null);
            }
            return;
        }
        await action(`/courses/${course.id}/enroll/`);
    }
