                                <div className="rounded-xl border border-slate-800 bg-slate-950/40 p-4"><div className="text-xs text-slate-500">Your earnings (after platform fee)</div><div className="mt-2 text-2xl font-black text-lime-200">${Number(filteredTransactionSummary.trainer_shares || 0).toFixed(2)}</div></div>
