                                    <div className="mt-4"><button className="btn btn-secondary w-full" onClick={() => { const match = courses.find(c => String(c.id) === String(course.course_id)); if (match) openCourse(match); else setPage('Discover'); }}>View course <ArrowUpRight size={14} /></button></div>
